import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.sRTLHEzD.js";const l=JSON.parse('{"title":"Send images with the composition bar","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/send_images_with_the_composition_bar.md","filePath":"documentation/send_images_with_the_composition_bar.md"}'),n={name:"documentation/send_images_with_the_composition_bar.md"};function s(r,e,h,m,p,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="send-images-with-the-composition-bar" tabindex="-1">Send images with the composition bar <a class="header-anchor" href="#send-images-with-the-composition-bar" aria-label="Permalink to &quot;Send images with the composition bar&quot;">​</a></h1><p>Use a pane&#39;s composition bar to add images and text, then send them to that pane&#39;s terminal.</p><h2 id="open-the-composition-bar" tabindex="-1">Open the composition bar <a class="header-anchor" href="#open-the-composition-bar" aria-label="Permalink to &quot;Open the composition bar&quot;">​</a></h2><p>In a pane, select its composition bar button in the pane header. The composition bar opens under that pane&#39;s terminal, and the text field receives focus.</p><h2 id="add-images-and-text" tabindex="-1">Add images and text <a class="header-anchor" href="#add-images-and-text" aria-label="Permalink to &quot;Add images and text&quot;">​</a></h2><ol><li>Select the <strong>plus</strong> button and choose one or more image files, or drag image files onto the open composition bar.</li><li>Type any accompanying text in the text field. Select an image preview to view it larger; use the side buttons or Left and Right keys to move between images, then press Escape to close the larger view.</li><li>Select <strong>Send</strong> or press Enter in the text field. The images are pasted into this pane&#39;s terminal first, followed by the text if the text field is not empty.</li></ol><p>The composition bar stays open after sending. If image pasting fails, the images that were not pasted and the text remain in the composition bar.</p><h2 id="remove-images-or-close-the-composition-bar" tabindex="-1">Remove images or close the composition bar <a class="header-anchor" href="#remove-images-or-close-the-composition-bar" aria-label="Permalink to &quot;Remove images or close the composition bar&quot;">​</a></h2><p>Select the remove button on an image preview to remove that image. To discard the current images and text and close the composition bar, select the same pane header button again or press Escape while the composition bar is open.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun_code/documentation/drop_images_on_a_composition_bar.html">Drop images on a composition bar</a>: choose which open composition bar receives dropped images.</li><li><a href="/heidrun_code/documentation/voice_input_across_panes.html">Use voice input across panes</a>: keep spoken text with the composition bar that started recording.</li></ul>',11)])])}const _=t(n,[["render",s]]);export{l as __pageData,_ as default};
